import logging
import re

from .file_logger import FileLogger


class IperfAnalyzer(object):
    """Iperf Analyzer"""

    PATTERN = r"\[\s*(\w+)\]\s*(\d+\.?\d*)\s*-\s*(\d+\.?\d*)\s*\w*\s*(\d*\.?\d*)\s*" \
              r"(\w*)\s*(\d*\.?\d*)\s*(\w+)\s*\/\w+\/?\s*(\d*\.?\d*)?\s*\w*\s*(\d*)?\/?\s*(\d*)?\s*\(?(\d*\.?\d*)%?\)?"
    LOG_LINE = """Data transfer statistics for Stream {}: min: {} MBit/s | max: {} MBit/s | average: {:.4f} MBit/s |
                  Packet loss (if applicable): {} % Observed drops: {} \n"""

    def __init__(self, logger=None, **kwargs):
        """

        :param logger:
        :param kwargs:
        """
        self.regexp = re.compile(IperfAnalyzer.PATTERN)
        if logger:
            self.logger = self._get_logger(logger)
        else:
            self.logger = logging.getLogger('ute_ue')

        Statistics.start_step = kwargs.get('start_step', 5) if kwargs.get('start_step', 5) else 5
        Statistics.threshold = kwargs.get('threshold', 0.05) if kwargs.get('threshold') else 0.05
        Statistics.num_messages = kwargs.get('lines_to_log_after_drop', 10)

        self.statistics = Statistics()

    def append_log_line(self, log_line):
        """
        Append log line.

        :param log_line:            log line to append
        """
        self.logger.debug(log_line + "\n")
        match = self.regexp.match(str(log_line))
        if match:
            stream_id = match.group(1)
            start_time = float(match.group(2))
            end_time = float(match.group(3))
            transferred_data = float(match.group(4))
            transferred_data_unit = match.group(5)
            bw_value = float(match.group(6))
            bw_unit = match.group(7)
            jitter = match.group(8)
            lost_packets = match.group(9)
            total_packets = match.group(10)
            lost_percentage = match.group(11)
        else:
            self.logger.debug("Line {} not match regex, skipping.".format(log_line))
            return

        bandwidth = Statistics.get_bandwidth(bw_value, bw_unit)
        self.logger.debug("append_log_line.self.statistics.streams: {}".format(self.statistics.streams))

        if bandwidth < 0:
            self.logger.debug("Error while reading unit land bandwidth: [%s] [%s] in line [%s]" % (bw_unit, bw_value, log_line))
        self.logger.debug("append_log_line.self.statistics: {}".format(self.statistics))
        self.logger.debug("append_log_line.parsed: stream_id:{}, bandwidth:{}, lost_packets:{}, total_packets:{}, start_time:{}, end_time:{}, "
                          "log_line:{}".format(stream_id, bandwidth, lost_packets, total_packets, start_time, end_time, log_line))
        self.statistics.update_or_add_stream(stream_id, bandwidth, lost_packets,
                                             total_packets, start_time, end_time, log_line)

    def get_results(self):
        """
        Get result.

        :return:                    dict with stats
        """
        stats_dict = self.statistics.as_dict()
        self.logger.debug("get_results.stats_dict: {}".format(stats_dict))
        self.logger.debug("get_results.statistics: {}".format(self.statistics))
        try:
            return stats_dict if len(list(stats_dict.keys())) > 1 else stats_dict[1]
        except KeyError as err:
            self.logger.debug("KeyError: {}".format(err))
            return {
                "min": 0,
                "max": 0,
                "avg": 0,
                "packet_loss": 0,
                "drop": []
            }

    def append_current_statistics(self):
        """Append current stats to log."""
        self.logger.info("append_current_statistics.self.statistics: {}".format(self.statistics))
        for _id, stream in self.statistics.as_dict().items():
            self.logger.info("append_current_statistics.inside for loop, id:{}, stream:{}".format(_id, stream))
            log_line = self.LOG_LINE.format(_id, stream['min'], stream['max'], stream['avg'], stream['packet_loss'],
                                            stream['drop'])
            self.logger.info(log_line)

    def reset_statistics(self):
        """Reset current stats."""
        self.logger.info("Statistics reset called, performing statistics dump\n")
        self.append_current_statistics()
        self.statistics.reset()

    def _get_logger(self, logger):
        return logger


class Statistics(object):
    """Statistics"""
    start_step = 10  # initial lines to skip
    threshold = 0.05  # bandwidth threshold to start logging drop
    num_messages = 10  # num messages to log after drop

    def __init__(self):
        """Basic initialization."""
        self.streams = {}

    def reset(self):
        """
        Reset statistics.

        :return:
        """
        for stream in list(self.streams.values()):
            stream.reset()

    def update_or_add_stream(self, _id, bandwidth, lost, total, start_time, end_time, log_line):
        """
        :param _id:         stream id
        :param bandwidth:   bandwidth
        :param lost:        lost packets
        :param total:       total packets
        :param start_time:  start_time
        :param end_time:    end_time
        :param log_line:    log_line
        """
        if not self.streams.get(_id):
            self.streams[_id] = Stream()
        self.streams[_id].add_data(bandwidth, lost, total, start_time, end_time, log_line)

    def as_dict(self):
        """
        Return stream as dict.

        :return dict
        """
        out_dict = {}
        stream_number = 1
        for _id, stream in self.streams.items():
            if _id != "SUM":
                stream_id = stream_number
                stream_number += 1
            else:
                stream_id = "SUM"
            out_dict[stream_id] = stream.as_dict()
        return out_dict

    @staticmethod
    def get_bandwidth(amount, unit):
        """
        Return bandwidth in Mbits.

        :param amount:  bandwidth value
        :param unit:    bandwidth unit
        :return float
        """
        current_bandwidth = -1
        if unit == "Mbits":
            current_bandwidth = float(amount)
        elif unit == "Gbits":
            current_bandwidth = float(amount) * 1000
        elif unit == "Kbits":
            current_bandwidth = float(amount) / 1000
        elif unit == "bits":
            current_bandwidth = float(amount) / (1000 * 1000)
        # return -1
        return current_bandwidth


class Stream(object):
    """Stream object"""

    def __init__(self):
        """Basic initialization."""
        self._line_number = 0  # Log line number of current stream
        self._min_bw = -1  # Minimum bandwidth occurred, updated online
        self._max_bw = -1  # Maximum bandwidth occurred, updated online
        self._avg_bw = 0  # Average bandwidth, computed online
        self._current_bw = 0  # Bandwidth in current iteration
        self._previous_bw = 0  # Bandwidth in previous iteration
        self._lost_packets = 0  # Total number of lost packets
        self._total_packets = 0  # Total number of transmitted packets
        self._drops = []

        self.prev_log_line = ""
        self._drops_logger_count = 0

    @property
    def min_bw(self):
        """
        Return minimum bandwidth.

        :return: float
        """
        return round(0 if self._min_bw < 0 else self._min_bw, 8)

    @property
    def max_bw(self):
        """
        Return maximum bandwidth.

        :return: float
        """
        return round(0 if self._max_bw < 0 else self._max_bw, 8)

    @property
    def avg_bw(self):
        """
        Return average bandwidth.

        :return: float
        """
        return round(self._avg_bw, 8)

    @property
    def packet_loss(self):
        """
        Return packet loss [%].

        :return: float
        """
        total = (float(self._lost_packets) * 100 / float(self._total_packets)) if (self._total_packets != 0) else 0
        return round(total, 8)

    @property
    def drops(self):
        """
        Returns drops.

        :return: float
        """
        return self._drops

    # log line only for drops, should be removed, or changed  IMO ,,,, !!!!
    def add_data(self, bandwidth, lost, total, start_time, end_time, log_line):
        """
        :param bandwidth:   current bandwidth
        :param lost:        lost pakcets
        :param total:       total packets
        :param start_time:  start_time
        :param end_time:    end_time
        :param log_line:    log_line
        """
        if start_time == 0:
            # Ommiting summary calculations for each streams...
            return

        self._previous_bw = self._current_bw
        self._current_bw = bandwidth

        self._process_drops(log_line, lost, total)

        if self._line_number - 1 < Statistics.start_step:
            # logger.debug(
            #     "Current step {}, initial step {}. Omitting calculations for min/max/avg.".format(self._line_number,
            #                                                                                       Statistics.start_step))
            return

        self._process_min_bandwidth(bandwidth)
        self._process_max_bandwidth(bandwidth)
        self._process_avg_bandwidth(bandwidth)

    def _process_drops(self, log_line, lost, total):
        if self._previous_bw - self._current_bw > Statistics.threshold * self._previous_bw and self._drops_logger_count == 0:
            self._drops.append([self.prev_log_line])  # add new list
            self._drops_logger_count = Statistics.num_messages
        self._count_drops(log_line)
        self._lost_packets += int(lost) if lost else 0
        self._total_packets += int(total) if total else 0
        self.prev_log_line = log_line
        self._line_number += 1

    def _count_drops(self, log_line):
        drop_list_index = len(self._drops) - 1 if (len(self._drops) > 0) else -1
        if drop_list_index > -1:
            if self._drops_logger_count > 0 and len(self._drops[drop_list_index]) < Statistics.num_messages:
                self._drops_logger_count -= 1
                self._drops[drop_list_index].extend([log_line])
            elif len(self._drops[drop_list_index]) == Statistics.num_messages:
                self._drops_logger_count = 0
            elif len(self._drops[drop_list_index]) > Statistics.num_messages:
                raise Exception("Unknown error")

    def _process_avg_bandwidth(self, bandwidth):
        if self._line_number - Statistics.start_step > 0:
            self._avg_bw = (float(self._avg_bw) * float(self._line_number - Statistics.start_step - 1) + float(
                bandwidth)) / float(self._line_number - Statistics.start_step)
        else:
            self._avg_bw = float(bandwidth)

    def _process_max_bandwidth(self, bandwidth):
        self._max_bw = bandwidth if self._max_bw == -1 else (self._max_bw if self._max_bw > bandwidth else bandwidth)

    def _process_min_bandwidth(self, bandwidth):
        self._min_bw = bandwidth if self._min_bw == -1 else (self._min_bw if self._min_bw < bandwidth else bandwidth)

    def reset(self):
        """Reset stream stats."""
        self._avg_bw = 0
        self._total_packets = 0
        self._lost_packets = 0
        self._min_bw = -1
        self._max_bw = -1
        self._drops = []
        self._line_number = 0

    def as_dict(self):
        """
        Convert to dict.

        :return:     dict with stream stats
        """
        return {
            'min': self.min_bw,
            'max': self.max_bw,
            'avg': self.avg_bw,
            'packet_loss': self.packet_loss,
            'drop': self.drops
        }
